  if (src.length != _through + 1) return false;
  if (src.last.length <= _tailThrottleMinLength) return false;
  final elapsed = DateTime.now().millisecondsSinceEpoch - _lastTailProcessMs;
  return elapsed < _tailThrottleIntervalMs;
